{
 "title": "会员体验调研报告",
 "team": "用户研究组",
 "period": "2026 年 9 月 8 日至 19 日",
 "summary": "会员净推荐值 32，比上次调研高 5 分；配送准时最受认可，退款流程和客服响应是最主要的不满，集中在老会员。",
 "sample": { "responses": 2346, "interviews": 18, "rate": 11.4 },
 "nps": { "score": 32, "change": "+5", "promoters": 48, "passives": 36, "detractors": 16 },
 "satisfaction": [
  { "name": "配送准时", "score": 4.5, "change": "+0.2" },
  { "name": "商品新鲜", "score": 4.3, "change": "+0.1" },
  { "name": "会员价格", "score": 4.0, "change": "0.0" },
  { "name": "App 好用", "score": 3.9, "change": "+0.3" },
  { "name": "客服响应", "score": 3.2, "change": "−0.2" },
  { "name": "退款流程", "score": 2.9, "change": "−0.4" }
 ],
 "pains": [
  { "name": "退款要等太久", "share": 38 },
  { "name": "客服排队长", "share": 31 },
  { "name": "缺货替换不提醒", "share": 22 },
  { "name": "会员券难用", "share": 17 },
  { "name": "配送时段少", "share": 12 }
 ],
 "segments": [
  { "name": "新会员（半年内）", "n": 812, "nps": 41, "csat": 4.2 },
  { "name": "老会员（一年以上）", "n": 1034, "nps": 24, "csat": 3.8 },
  { "name": "高频（每周 2 单以上）", "n": 655, "nps": 36, "csat": 4.1 },
  { "name": "低频（每月 2 单以下）", "n": 487, "nps": 19, "csat": 3.6 }
 ],
 "quotes": [
  { "text": "退一盒坏掉的草莓要等五天，钱不多，就是很烦。", "who": "老会员，上海" },
  { "text": "配送一直很准时，这是我续费的主要原因。", "who": "高频会员，杭州" },
  { "text": "缺货时直接换了别的牌子，也没问我一声。", "who": "老会员，苏州" },
  { "text": "客服要排二十分钟，最后还是自己在 App 里找到了入口。", "who": "低频会员，南京" }
 ],
 "recommendations": [
  { "title": "小额退款秒退", "detail": "50 元以下的生鲜退款免审核，预计覆盖七成退款申请。" },
  { "title": "缺货替换先确认", "detail": "替换商品前推送确认，用户 5 分钟内未回复则按备注处理。" },
  { "title": "老会员专属客服", "detail": "会员满一年进入优先队列，目标排队时间 3 分钟以内。" }
 ]
}
